import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Gifts and two-way trades","description":"","frontmatter":{"pageId":"players/gifts-trades","contentRevision":1},"headers":[],"relativePath":"en/players/gifts-trades.md","filePath":"en/players/gifts-trades.md"}'),i={name:"en/players/gifts-trades.md"};function n(o,e,d,l,f,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="gifts-and-two-way-trades" tabindex="-1">Gifts and two-way trades <a class="header-anchor" href="#gifts-and-two-way-trades" aria-label="Permalink to &quot;Gifts and two-way trades&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Gift:</strong> select a player and the transfer contents. The recipient accepts, refuses or postpones the decision; refusal returns escrow to the sender. Unanswered gifts are declined after 7 days by default. Gift preferences and blocking affect new offers.</p><p><strong>Trade:</strong> open an offer and add items, pawns, silver and a note. The other party edits their side. Any edit invalidates earlier confirmations: both parties must confirm the same revision. Cancellation or expiry returns each contribution to its owner. Review the final contents before confirming.</p><p>After a disconnect, refresh trade state first. Do not send the same goods as a new gift while the first operation is unresolved.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The default trade lifetime is 7 days with at most 5 open trades. Closed trading and gift refusal are separate preferences. Accepting goods never requires sharing a password.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./chat-pings">Chat, messages and pings</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',10)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
